import{k as s}from"./index-CNv0BdFy.js";const o={async getAll(e){return(await s.get("/employees",{params:e})).data},async getById(e){return(await s.get(`/employees/${e}`)).data},async create(e){return(await s.post("/employees",e)).data},async update(e,t){return(await s.put(`/employees/${e}`,t)).data},async remove(e){return(await s.delete(`/employees/${e}`)).data},async getStats(){return(await s.get("/employees/stats")).data},async getAssets(e){return(await s.get(`/employees/${e}/assets`)).data}};export{o as e};
